function messageMatches(m,p){const x=p.checkpoint.payload;return m?.author?.id===BOT&&m.channel_id===x.channel_id&&m.content===x.expected_body.content&&(m.embeds||[]).some(e=>e.footer?.text===x.marker)&&(!x.attachment_text?!(m.attachments||[]).length:((m.attachments||[]).length===1&&m.attachments[0].filename===x.file_name&&Number(m.attachments[0].size)===Buffer.byteLength(x.attachment_text,'utf8')));}
function resolve(request,r){const all=values(r);let id=request.record_id;
 if(request.mode==='scan'){const due=all.filter(x=>x.record_type==='DELIVERY_JOB'&&x.dataset_id==='real'&&['STAGED','PROCESSING','IN_FLIGHT','RETRY_WAIT'].includes(x.status)&&(!x.next_retry_at||Date.parse(x.next_retry_at)<=Date.now()));due.sort((a,b)=>Date.parse(a.updated_at)-Date.parse(b.updated_at));if(!due.length)return {route:0,status:'NO_DUE_DELIVERIES'};id=due[0].record_id;}
 if(request.mode==='newsletter')id='delivery:news:'+request.message_id;
 if(request.mode==='delivery'||request.mode==='demo')id='delivery:'+sha(request.delivery_key).slice(0,40);
 if(!/^delivery:[a-zA-Z0-9:_-]{8,150}$/.test(id||''))throw Error('DELIVERY_ID_INVALID');
 const matches=all.filter(x=>x.record_id===id);if(matches.length>1)throw Error('DUPLICATE_DELIVERY_JOB');
 let rec,checkpoint,progress={},rn=null;
 if(matches.length){rec=cp(matches[0]);rn=rec._row;delete rec._row;checkpoint=JSON.parse(rec.analysis_checkpoint_json);progress=JSON.parse(rec.progress_json||'{}');if(checkpoint.version!=='delivery-1.0')throw Error('DELIVERY_VERSION_CONFLICT');if(request.mode==='delivery'&&checkpoint.input_hash!==sha(JSON.stringify(request.payload)))throw Error('DELIVERY_PAYLOAD_CONFLICT');if(['COMPLETE','REVIEW'].includes(rec.status))return {route:0,...result({record:rec,checkpoint}, {duplicate:true})};if(rec.next_retry_at&&Date.parse(rec.next_retry_at)>Date.now())return {route:0,...result({record:rec,checkpoint},{not_due:true})};}
 else{if(['scan','resume'].includes(request.mode))throw Error('DELIVERY_RECORD_NOT_FOUND');rec=Object.fromEntries(HEADERS.map(k=>[k,'']));const ts=now();Object.assign(rec,{record_id:id,record_type:'DELIVERY_JOB',message_key:request.delivery_key||request.message_id,gmail_message_id:request.message_id||'',source_id:request.payload?.source_id||'newsletter',received_at:ts,operation_id:id,stage:'QUEUED',status:'STAGED',attempt_count:0,created_at:ts,updated_at:ts,schema_version:'2.1',dataset_id:request.mode==='demo'?'fictional':'real'});checkpoint={version:'delivery-1.0',kind:request.mode==='newsletter'?'NEWS':'DELIVERY',message_id:request.message_id||null,payload:request.payload?payload(request.payload,id):null,input_hash:request.payload?sha(JSON.stringify(request.payload)):null,scenario:request.mode==='demo'?request.scenario:null};}
 const lock_id=100000000+parseInt(sha(id).slice(0,7),16);const lock_value=JSON.stringify({workflow:'I',owner:String($execution.id),record_id:id});return {route:1,row:rn,record:rec,checkpoint,progress,lock_id,lock_value,claim_body:{requests:[{createDeveloperMetadata:{developerMetadata:{metadataId:lock_id,metadataKey:'ipt_delivery_writer_v1',metadataValue:lock_value,visibility:'DOCUMENT',location:{spreadsheet:true}}}}]}};
}
function nextAttempt(p){p.record.attempt_count=Number(p.record.attempt_count)+1;if(p.record.attempt_count>3&&!p.checkpoint.delivery_started_at)return review(p,'RETRY_EXHAUSTED');p.progress.attempts=[...(p.progress.attempts||[]),{attempt:p.record.attempt_count,execution_id:String($execution.id),at:now(),phase:p.checkpoint.delivery_started_at?'RECONCILE':p.checkpoint.payload?'DELIVERY':'NEWS'}].slice(-6);p.record.status=p.checkpoint.delivery_started_at?'IN_FLIGHT':p.checkpoint.payload?'STAGED':'PROCESSING';p.record.stage=p.checkpoint.delivery_started_at?'RECONCILE_PENDING':p.checkpoint.payload?'PAYLOAD_FROZEN':'NEWS_PREPARATION';p.record.next_retry_at=new Date(Date.now()+60000).toISOString();return write(p);}
function workerResult(r,p){if(r.status==='NO_OP'||r.status==='NEWS_ALREADY_DELIVERED')return complete(p,null,r.status==='NO_OP'?'NO_ELIGIBLE_CONTENT':'LEGACY_DELIVERY_COMPLETE');if(r.status==='NEWS_PAYLOAD_READY'&&r.payload){p.checkpoint.payload=payload(r.payload,p.record.record_id);p.record.source_id=r.payload.source_id;p.record.origin_ref=r.payload.source_url||'';p.record.content_hash=sha(r.payload.content);p.record.status='STAGED';p.record.stage='PAYLOAD_FROZEN';return write(p);}const msg=String(r.error?.message||r.error||r.message||'NEWS_WORKER_FAILED');if(/SCHEMA|EVIDENCE|FIELDS_INVALID|OUTPUT_LIMIT|SOURCE_NOT_AUTHORIZED|AUTHENTICATION_FAILED|SENDER_NOT|CONTENT_CHANGED|PARTIAL_OR_DUPLICATE|INVALID_JSON/.test(msg))return review(p,msg.slice(0,150));return retry(p,'NEWS_PREPARATION_FAILED');}
function startSend(p){if(p.record.status==='REVIEW'||p.record.status==='COMPLETE')return {...p,route:0};if(p.checkpoint.scenario==='TEMP_503'&&Number(p.record.attempt_count)===1){p.progress.simulated_failure='PRE_SEND_503_NO_HTTP_SEND';return {...retry(p,'DEMO_SIMULATED_503',15),route:0};}p.checkpoint.delivery_started_at=p.checkpoint.delivery_started_at||now();p.record.status='IN_FLIGHT';p.record.stage='DISCORD_SEND_PENDING';p.record.next_retry_at=new Date(Date.now()+60000).toISOString();return {...write(p),route:1};}
function afterSend(r,p){const b=r.body??r,code=Number(r.statusCode||0);if(code===200&&messageMatches(b,p)){if(p.checkpoint.scenario==='AFTER_SEND'&&Number(p.record.attempt_count)===1)return {...p,skip_final_write:true,demo_interrupted:true};return complete(p,b);}if(code===429){delete p.checkpoint.delivery_started_at;return retry(p,'DISCORD_RATE_LIMIT',Math.max(15,Number(b.retry_after)||300));}if(code>=400&&code<500)return review(p,'DISCORD_PERMANENT_'+code);p.record.status='IN_FLIGHT';p.record.stage='DELIVERY_UNCERTAIN';p.record.error_code='DISCORD_OUTCOME_UNKNOWN';p.record.error_summary='Reconcile channel history before any resend.';p.record.next_retry_at=new Date(Date.now()+60000).toISOString();return write(p);}
function reconcile(r,p){if(Number(r.statusCode)!==200||!Array.isArray(r.body))return retry(p,'DISCORD_HISTORY_UNAVAILABLE');const found=r.body.filter(m=>messageMatches(m,p));p.progress.reconcile_checks=Number(p.progress.reconcile_checks||0)+1;if(found.length===1)return complete(p,found[0],'RECONCILED');if(found.length>1)return review(p,'DUPLICATE_REMOTE_MESSAGES');return review(p,r.body.length>=100?'DISCORD_SEARCH_WINDOW_FULL':'DELIVERY_NOT_FOUND_REVIEW');}
function release(p){p.release_body={requests:[{deleteDeveloperMetadata:{dataFilter:{developerMetadataLookup:{metadataId:p.lock_id,metadataKey:'ipt_delivery_writer_v1',metadataValue:p.lock_value,visibility:'DOCUMENT'}}}}]};return p;}

const r=$input.first().json,p=$('Prepare owner-only delivery release').first().json,b=r.body??r;if(r.statusCode!==200||b.replies?.[0]?.deleteDeveloperMetadata?.deletedDeveloperMetadata?.length!==1)throw Error('DELIVERY_LOCK_RELEASE_FAILED');return packet(result(p,{demo_interrupted:p.demo_interrupted===true,lock_released:true}));
